mapper.update:
UPDATE travel_diary
title = #{title}, content = #{content}, location = #{location}, travel_date = #{travelDate}, weather = #{weather}, mood = #{mood}, images = #{images}, tags = #{tags}, cover_image = #{coverImage}, is_public = #{isPublic},
WHERE id = #{id} AND user_id = #{userId}

mapper.select:
SELECT * FROM travel_diary
WHERE user_id = #{userId}

    AND tags LIKE CONCAT('%', #{tag}, '%')


    AND location = #{location}


    AND travel_date >= #{startDate}


    AND travel_date <= #{endDate}

ORDER BY travel_date DESC, created_at DESC
